import sys,json
from pathlib import Path
root,checkout=Path(sys.argv[1]),Path(sys.argv[2]); operation=sys.argv[3]
sys.path.insert(0,str(checkout/"tools/nr-color"))
import hmd_assess as h,hmd_capture as c,assess
plan=h.read_json(root/"private-plan.json")
assert h.digest(root/"private-plan.json")==h.read_json(root/"campaign-index.json")["planSha256"]
def payload(p):return json.loads(h.read_json(p)["content"][0]["text"])
if operation=="stamps":
 m=h.read_json(Path(sys.argv[4]));stamps={}
 for child in m["children"]:
  nr=child["actual"]["acquisition"].get("nrEvidence",{})
  for obs in [nr.get("engineExposure",{})]+[nr.get(e,{}).get("exposure",{}) for e in h.EYES]:
   if all(isinstance(obs.get(k),int) and obs[k]>0 for k in ("frame","epoch","sequence")):
    stamp={k:obs[k] for k in ("frame","epoch","sequence")};stamps[tuple(stamp.values())]=stamp
 print(json.dumps({"stamps":list(stamps.values())}))
elif operation=="expected":
 number=int(sys.argv[4]); suffix=sys.argv[5] if len(sys.argv)>5 else ""; nr=payload(root/f"steps/{number:03}{suffix}/applied.json")["neuralRendering"]
 candidate=plan["candidateMapping"][plan["schedule"][number-1]["candidateId"]]
 color=nr["requestedConfiguration"]["color"]
 expected={"configuration":nr["requestedConfiguration"],"configurationFingerprint":nr["requestedConfigurationFingerprint"],"insertion":"upscaled_center","maximumRenderFrameAge":0,"requiresCapturedExposure":False,"exposureAge":0}
 errors=[]
 for pair in nr["captureEvidence"]["routes"]:
  try:
   expected.update(colorRevision=pair["left"]["colorRevision"],inputEpoch=pair["left"]["inputEpoch"])
   h.check_nr(pair,expected,candidate,{"engineFrame":max(pair[e]["frame"] for e in h.EYES)},require_exposure=False)
   scout=h.read_json(Path(payload(root/"scout4Get.json")["result"]["manifest"]["finalPath"]))
   expected["planes"]={p["eye"]:p for p in scout["children"][0]["actual"]["acquisition"]["planes"]}
   print(json.dumps({"ok":True,"expected":expected}));break
  except Exception as e:errors.append(str(e))
 else:print(json.dumps({"ok":False,"errors":errors}))
elif operation=="validate":
 number=int(sys.argv[4]);suffix=sys.argv[5] if len(sys.argv)>5 else "";entry=h.read_json(root/f"steps/{number:03}{suffix}/entry.json")
 index=h.read_json(root/"campaign-index.json");errors=[];pairs=[]
 manifest=h.read_json(h.committed(entry["manifest"],root))
 candidate=plan["candidateMapping"][plan["schedule"][number-1]["candidateId"]]
 try:
  h.require(manifest["producer"]==index["producer"] and manifest["sessionId"]==index["sessionId"],"producer/session changed")
  h.require(manifest["state"]=="final" and manifest["counts"]["inFlight"]==0,"sequence not final")
  for child in manifest["children"]:
   try:
    pair=h.check_pair(child,Path(entry["manifest"]["path"]).parent,entry["expected"],candidate,plan["regionPolicy"],capture_diagnostics=entry["captureDiagnostics"],sequence=manifest)
    h.check_camera(pair["acquisition"],plan["fixedScene"])
    pairs.append(pair)
   except Exception as e:errors.append({"ordinal":child["ordinal"],"error":str(e)})
  entry["validatedPairs"]=len(pairs);entry["excludedChildren"]=errors
  entry["motionEvidence"]=c.acquisition_motion(pairs,plan)
  recording=entry["recording"]
  source=Path("D:/Skyrim Mods/mods/Synthesis Patch (SFW)/SKSE/Plugins/devbench/recordings")/Path(recording["path"]).name
  recording["artifacts"]=[h.preserve(source,root/f"recordings/{number:03}.json")]
  entry["recordedScene"]=h.recording_scene(h.read_json(source),plan)
  h.require(recording["meta"]["correlationId"]==entry["captureSessionId"],"record correlation differs")
  h.require(recording["limitReached"] is False and recording["unrecordedTailMs"]==0,"incomplete recording")
  h.require(entry["recordedScene"]["qualified"],entry["recordedScene"]["reason"])
  h.require(len(pairs)>=12,"insufficient accepted pairs")
  h.require(entry["motionEvidence"]["available"],entry["motionEvidence"]["reason"])
 except Exception as e:entry["error"]=str(e)
 index["sequences"].append(entry);assess.atomic_json(root/"campaign-index.json",index)
 result={"ok":not entry.get("error"),"validatedPairs":len(pairs),"errors":errors,"error":entry.get("error")}
 if number==3 and result["ok"]:
  baseline=c.baseline_repeatability(index["sequences"],plan)
  h.save_json(root/"baseline-repeatability-gate.json",baseline)
  result.update(ok=baseline["qualified"],baselineExclusionCount=len(baseline["excluded"]),baselineGatePath=str(root/"baseline-repeatability-gate.json"))
  if not baseline["qualified"]:result["error"]="unchanged baselines are motion/exposure confounded"
 print(json.dumps(result))

const root=load("retestEvidence"),work=load("work"),parse=r=>{if(r.isError)throw Error(r.content[0].text);return JSON.parse(r.content[0].text)};
async function save(path,value){await tools.apply_patch("*** Begin Patch\n*** Add File: "+root+"/"+path+"\n"+JSON.stringify(value,null,2).split("\n").map(x=>"+"+x).join("\n")+"\n*** End Patch");}
async function call(name,args,path){const r=await tools[name](args);await save(path,r);return parse(r);}
async function offline(op,arg){let r=await tools.exec_command({cmd:"$env:PYTHONPATH='"+work+"/build/validation/hmd-python-deps'; python '"+root+"/direct-offline.py' '"+root+"' '"+work+"' "+op+" "+arg,max_output_tokens:3000});let out=r.output;while(r.session_id){r=await tools.write_stdin({session_id:r.session_id,chars:"",yield_time_ms:1000,max_output_tokens:3000});out+=r.output;}if(r.exit_code!==0)throw Error(out);return JSON.parse(out);}
let status=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},"baseline-applied.json");
store("lastOwnedConfiguration",status.neuralRendering.requestedConfiguration);
for(let n=1;n<=3;n++)await save("steps/"+String(n).padStart(3,"0")+"/applied.json",{content:[{type:"text",text:JSON.stringify(status)}],isError:false});
const exp=await offline("expected","1");if(!exp.ok)throw Error(JSON.stringify(exp));store("fastExpected",exp.expected);
const corr="nr-hmd-fast-baselines-"+Date.now();store("activeRecordCorrelation",corr);
const rec=await call("mcp__devbench_vr__record",{action:"start",correlationId:corr,intervalMs:50,maximumDurationMs:180000},"baseline-record-start.json");
if(!rec.recording)throw Error("record failed");const caps=[];
for(let n=1;n<=3;n++){
 const prefix="steps/"+String(n).padStart(3,"0")+"/";
 const capture={...load("captureDescriptor"),destination:{policy:"absolute",directory:root+"/"+prefix+"frames",baseName:"frame",overwrite:"never"},tags:{captureInteractionSessionId:corr}};
 const start=await call("mcp__devbench_vr__communityshaders_screenshot",{action:"sequence_start",contractMajor:1,clientId:"nr-colour-assessment",commandId:corr+"-"+n+"-start",sequence:{frameCount:12,useSettings:false,schedule:{basis:"wall_clock",intervalMs:500,startDelayMs:0,pausePolicy:"hold"},backpressure:{policy:"skip",maximumConsecutiveSkips:20},failurePolicy:"continue",capture,packaging:{frameManifest:true,previewVideo:{requested:false,required:false,framesPerSecond:2}}}},prefix+"capture-start.json");
 const id=start.result.requestId;store("activeScreenshotRequest",id);
 await new Promise(r=>setTimeout(r,6200));
 let got;
 for(let k=0;k<5;k++){
  got=await call("mcp__devbench_vr__communityshaders_screenshot",{action:"request_get",contractMajor:1,clientId:"nr-colour-assessment",commandId:corr+"-"+n+"-get-"+k,requestId:id},prefix+"capture-get-"+k+".json");
  if(["completed","completed_with_warnings","failed","failed_partial","stopped","cancelled","cancelled_partial","rejected"].includes(got.result.state))break;
 }
 const r=got.result;if(!["completed","completed_with_warnings"].includes(r.state))throw Error("capture failed "+r.state);
 store("activeScreenshotRequest",null);const manifest=r.artifacts.find(x=>x.path===r.manifest.finalPath);if(!manifest)throw Error("manifest missing");
 const stamps=await offline("stamps","\'"+manifest.path+"\'"); const captureDiagnostics=await call("mcp__devbench_vr__communityshaders_nr_color",{action:"capture_diagnostics",stamps:stamps.stamps},prefix+"exposure-raw.json");
 caps.push({scheduleOrdinal:n,prefix,terminalReceipt:r,manifest,captureDiagnostics});store("fastCaptured",caps);text({captured:n,pairs:r.counts.written});await yield_control();
}
const recording=await call("mcp__devbench_vr__record",{action:"stop",expectedCorrelationId:corr},"baseline-record-stop.json");store("activeRecordCorrelation",null);
const after=await call("mcp__devbench_vr__communityshaders_renderscale",{action:"nr_status"},"baseline-after.json");
function sort(x){return Array.isArray(x)?x.map(sort):x&&typeof x==="object"?Object.fromEntries(Object.keys(x).sort().map(k=>[k,sort(x[k])])):x;}
if(JSON.stringify(sort(after.neuralRendering.requestedConfiguration))!==JSON.stringify(sort(load("lastOwnedConfiguration"))))throw Error("configuration ownership changed");
for(const e of caps){
 const diagnostics=e.captureDiagnostics;
 const dp=root+"/"+e.prefix+"capture-diagnostics.json";await save(e.prefix+"capture-diagnostics.json",diagnostics);
 const dr=await tools.exec_command({cmd:"$p='"+dp+"'; [pscustomobject]@{path=$p;bytes=(Get-Item -LiteralPath $p).Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()} | ConvertTo-Json -Compress",max_output_tokens:300});
 await save(e.prefix+"entry.json",{scheduleOrdinal:e.scheduleOrdinal,expected:exp.expected,captureSessionDirectory:root+"/"+e.prefix,captureSessionId:corr,manifest:e.manifest,terminalReceipt:e.terminalReceipt,captureDiagnostics:diagnostics,captureDiagnosticsArtifact:JSON.parse(dr.output),recording,transport:"direct_mcp",userSessionAuthorization:load("userSessionAuthorization")});
 const v=await offline("validate",String(e.scheduleOrdinal));await save(e.prefix+"validation.json",v);text({validated:e.scheduleOrdinal,...v});if(!v.ok){store("campaignFailure",{ordinal:e.scheduleOrdinal,...v});break;}
}

