import json,copy,shutil,sys
from pathlib import Path
r=Path(sys.argv[1]);old=Path(sys.argv[2]);w=Path(sys.argv[3]);sys.path.insert(0,str(w/'tools/nr-color'));import hmd_assess as h,hmd_capture as c
def p(name):return json.loads(h.read_json(r/(name+'.json'))['content'][0]['text'])
m=h.read_json(Path(p('scout4Get')['result']['manifest']['finalPath']));acq=m['children'][0]['actual']['acquisition'];meta=p('scout4RecordStop')['meta']
regions=h.read_json(old/'regions.json');spec=h.read_json(old/'spec.json');fid=r.name+'-fov095-character-mask';regions['sceneFingerprint']=spec['sceneFingerprint']=fid
for eye,x in [('left',2100),('right',1600)]:
 for reg in regions['eyes'][eye]['regions']:
  if reg['id']=='barrel_ring':reg.update(rect=[x,1190,110,40],description='Upper metal hoop with faint blue/orange reflection; no bright clipping coverage')
camera={k:acq['cameraEvidence'][k] for k in ['view','projection','positionAdjust']};camera.update(viewTolerance=0.001,projectionTolerance=0.000001,positionAdjustTolerance=0.2)
spec['fixedScene']={'cameraEvidence':camera,'recordingScene':{k:meta[k] for k in ['cell','cellFormID','interior','weatherFormID','worldspace','worldspaceFormID']},'gameHour':meta['gameHour'],'gameHourTolerance':0.01,'entryPoint':meta['entryPoint'],'timeScale':0,'originalTimeScale':20,'trackingPolicy':'Physical tracking, unchanged actor AI per user stationary-scene instruction; no synthetic pose or AI mutation.'}
fixed=copy.deepcopy(acq['nrEvidence']['configuration']['upscaling']);fixed.pop('neuralRenderingEnabled');spec['fixedSettings']=fixed
plan=h.make_plan(spec,regions,19417);c.validate_plan(plan);c.validate_fixed_scene(plan['fixedScene'])
for name,obj in [('regions',regions),('spec',spec),('private-plan',plan)]:h.save_json(r/(name+'.json'),obj)
i=h.read_json(old/'campaign-index.json')
i={k:i[k] for k in ['schema','devbench','userSessionAuthorization']}
i.update(planPath=str(r/'private-plan.json'),planSha256=h.digest(r/'private-plan.json'),sceneFingerprint=fid,fixedSettings=fixed,producer=m['producer'],sessionId=m['sessionId'],sequences=[],performanceCampaign=False,complete=False,untestedConditions=plan['untestedConditions'])
h.save_json(r/'campaign-index.json',i)
settings={key:c.candidate_colour(c.colour_editable(acq['nrEvidence']['configuration']['color']),candidate) for key,candidate in plan['candidateMapping'].items()}
h.save_json(r/'candidate-configurations.json',settings);h.save_json(r/'plan-data.json',{'plan':plan,'schedule':plan['schedule'],'candidateConfigurations':settings})
shutil.copy2(old/'direct-offline.py',r/'direct-offline.py')
src=Path('D:/Skyrim Mods/mods/Synthesis Patch (SFW)/SKSE/Plugins/devbench/recordings')/Path(p('scout4RecordStop')['path']).name;h.preserve(src,r/'scout/recording.json')
print(json.dumps({'steps':len(plan['schedule']),'planSha256':i['planSha256'],'gameHour':meta['gameHour']}))

